parameters.functionCode:
// Score the incoming application against BOSSMoves criteria
const data = $input.first().json;
let score = 0;
const notes = [];

// Revenue tier (max 35)
const rev = (data.revenue || '').toLowerCase();
if (rev.includes('5m')) { score += 35; notes.push('revenue_5m+'); }
else if (rev.includes('2m')) { score += 30; notes.push('revenue_2m_5m'); }
else if (rev.includes('1m')) { score += 25; notes.push('revenue_1m_2m'); }
else if (rev.includes('300k')) { score += 20; notes.push('revenue_300k_1m'); }
else if (rev.includes('100k')) { score += 12; notes.push('revenue_100k_300k'); }
else { score += 3; notes.push('revenue_under_100k'); }

// Timeline urgency (max 25)
const tl = (data.timeline || '').toLowerCase();
if (tl.includes('week')) { score += 25; notes.push('timeline_urgent'); }
else if (tl.includes('2 weeks')) { score += 20; notes.push('timeline_fast'); }
else if (tl.includes('30 days')) { score += 12; notes.push('timeline_normal'); }
else { score += 3; notes.push('timeline_cold'); }

// Package selected (max 20)
if (data.package === 'dominion') { score += 20; notes.push('pkg_dominion'); }
else if (data.package === 'empire') { score += 15; notes.push('pkg_empire'); }
else if (data.package === 'system') { score += 10; notes.push('pkg_system'); }
else { score += 5; notes.push('pkg_unsure'); }

// Has biggest leak detail (max 20)
if ((data.biggest_leak || '').length > 80) { score += 20; notes.push('leak_detailed'); }
else if ((data.biggest_leak || '').length > 20) { score += 10; notes.push('leak_brief'); }

return [{ json: { ...data, gate_score: score, gate_notes: notes, assigned_temperature: score >= 70 ? 'hot' : score >= 50 ? 'warm' : 'cold' } }];

